import pyomo.environ as pyo

DATA = {
    "products": ["color", "bw"],
    "resources": ["color_team", "bw_team", "paper_tray_machine"],
    "profit": {"color": 200, "bw": 70},
    "capacity": {"color_team": 20, "bw_team": 30, "paper_tray_machine": 35},
    "usage": {
        ("color_team", "color"): 1,
        ("color_team", "bw"): 0,
        ("bw_team", "color"): 0,
        ("bw_team", "bw"): 1,
        ("paper_tray_machine", "color"): 1,
        ("paper_tray_machine", "bw"): 1,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])
    model.R = pyo.Set(initialize=d["resources"])

    lb = {p: 0 for p in d["products"]}
    model.x = pyo.Var(model.P, domain=pyo.NonNegativeIntegers, bounds=lambda m, p: (lb[p], None))

    def profit_rule(m):
        return sum(d["profit"][p] * m.x[p] for p in m.P)

    model.obj = pyo.Objective(rule=profit_rule, sense=pyo.maximize)

    def capacity_rule(m, r):
        return sum(d["usage"][(r, p)] * m.x[p] for p in m.P) <= d["capacity"][r]

    model.capacity = pyo.Constraint(model.R, rule=capacity_rule)

    return model


